#!/usr/bin/env node
// Generates every platform's friendly-error files from packages/shared/friendly_error/.
//   node scripts/build_friendly_errors.mjs          write the files
//   node scripts/build_friendly_errors.mjs --check  fail if any generated file is stale
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { moodSvg, MOODS } from "../packages/shared/friendly_error/art.mjs";
import { classifyStatus, KIND_MOOD } from "../packages/shared/friendly_error/classify.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SRC = join(ROOT, "packages/shared/friendly_error");
const read = (name) => readFileSync(join(SRC, name), "utf8");

const copyAll = JSON.parse(read("copy.json"));
const COPY = Object.fromEntries(Object.entries(copyAll).filter(([k]) => !k.startsWith("_")));
const PAGE_CSS = read("page.css").trim();
const RUNTIME = read("runtime.js");
const CLASSIFY_SRC = readFileSync(join(SRC, "classify.mjs"), "utf8")
  .replace(/export /g, "")
  .replace(/^\/\/.*\n/gm, "");
const HEADER = "// GENERATED by scripts/build_friendly_errors.mjs from packages/shared/friendly_error. Do not edit.\n";

const artAnimated = Object.fromEntries(MOODS.map((m) => [m, moodSvg(m, {animated: true})]));
const artStatic = Object.fromEntries(MOODS.map((m) => [m, moodSvg(m, {animated: false, size: 240})]));

function sharedStaticJs() {
  return `${HEADER}(function () {
"use strict";
var ART = ${JSON.stringify(artAnimated)};
var COPY = ${JSON.stringify(COPY)};
var PAGE_CSS = ${JSON.stringify(PAGE_CSS)};
var KIND_MOOD = ${JSON.stringify(KIND_MOOD)};
${CLASSIFY_SRC.replace(/const KIND_MOOD[^\n]*\n/, "")}
${RUNTIME}
var cs = document.currentScript;
if (cs && cs.dataset && cs.dataset.watch) {
  watchFetch({match: new RegExp(cs.dataset.watch), ignore: cs.dataset.ignore ? new RegExp(cs.dataset.ignore) : null});
  enableOfflineBanner();
}
window.SalaFriendlyError = {show: show, hide: hide, watchFetch: watchFetch, enableOfflineBanner: enableOfflineBanner, classifyStatus: classifyStatus, art: ART, copy: COPY};
})();
`;
}

function tsModule(art) {
  return `${HEADER}export type FriendlyKind = "offline" | "network" | "notfound" | "notimpl" | "oops";
export type FriendlyMood = "tears" | "surprised" | "thinking" | "calm";
export type FriendlyCopy = { title: string; body: string; hint: string };
export type FriendlyCommon = { tryAgain: string; retryIn: string; home: string; back: string; status: string; checking: string; stillDown: string };
export const FRIENDLY_ART: Record<FriendlyMood, string> = ${JSON.stringify(art, null, 2)};
export const FRIENDLY_COPY: Record<string, Record<string, FriendlyCopy> & { common: FriendlyCommon }> = ${JSON.stringify(COPY, null, 2)} as never;
export const FRIENDLY_PAGE_CSS = ${JSON.stringify(PAGE_CSS)};
export const FRIENDLY_KIND_MOOD: Record<FriendlyKind, FriendlyMood> = ${JSON.stringify(KIND_MOOD)};
export function classifyStatus(status: number | null | undefined, opts?: { offline?: boolean; timeout?: boolean }): FriendlyKind | null {
  const o = opts || {};
  const code = Number(status) || 0;
  if (o.offline) return "offline";
  if (o.timeout || code === 0) return "network";
  if (code === 404 || code === 410) return "notfound";
  if (code === 501) return "notimpl";
  if (code === 502 || code === 503 || code === 504 || (code >= 520 && code <= 524)) return "network";
  if (code >= 500) return "oops";
  return null;
}
`;
}

function pageHtml(code, kind) {
  const mood = KIND_MOOD[kind];
  const en = COPY.en[kind];
  const data = {copy: COPY, kind};
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex"><title>${en.title} - Salareen</title>
<style>html,body{margin:0;height:100%;background:#0b1020}${PAGE_CSS}.sfe-screen{position:fixed}</style></head>
<body><main class="sfe-screen" role="alert"><div class="sfe-stars"></div><div class="sfe-card">${artAnimated[mood]}
<h1 class="sfe-title" id="t">${en.title}</h1><p class="sfe-body" id="b">${en.body}</p><p class="sfe-hint" id="h">${en.hint}</p>
<div class="sfe-actions">${kind === "notfound" ? "" : `<a class="sfe-btn sfe-primary" id="r" href="javascript:location.reload()">${COPY.en.common.tryAgain}</a>`}<a class="sfe-btn${kind === "notfound" ? " sfe-primary" : ""}" id="g" href="/">${COPY.en.common.home}</a></div>
<span class="sfe-code" id="c">${COPY.en.common.status.replace("{code}", String(code))}</span></div></main>
<script>(function(){var D=${JSON.stringify(data)};var tags=[].concat(navigator.languages||[navigator.language||"en"]);var loc="en";for(var i=0;i<tags.length;i++){var b=String(tags[i]).toLowerCase().split("-")[0];if(D.copy[b]){loc=b;break}}
var L=D.copy[loc],k=L[D.kind]||D.copy.en[D.kind],c=Object.assign({},D.copy.en.common,L.common||{});document.documentElement.lang=loc;
document.getElementById("t").textContent=k.title;document.getElementById("b").textContent=k.body;document.getElementById("h").textContent=k.hint;
var rb=document.getElementById("r");if(rb)rb.textContent=c.tryAgain;document.getElementById("g").textContent=c.home;document.getElementById("c").textContent=c.status.replace("{code}",${code});
${kind === "network" ? "var n=15,note=document.createElement('p');note.className='sfe-note';note.setAttribute('aria-live','polite');document.getElementById('c').before(note);setInterval(function(){n--;if(n<=0){location.reload();return}note.textContent=c.retryIn.replace('{n}',n)},1000);" : ""}
})();</script></body></html>
`;
}

function jsonBody(code, kind) {
  const c = COPY.en[kind];
  return JSON.stringify({error: kind, status: code, friendly_message: `${c.title}. ${c.body}`, friendly: c}) + "\n";
}

const PAGES = [[404, "notfound"], [500, "oops"], [502, "network"], [503, "network"], [504, "network"]];

function yamlBlock(name, content) {
  return `  ${name}: |\n${content.split("\n").map((l) => (l ? `    ${l}` : "")).join("\n")}`;
}

function k8sManifest() {
  const files = [];
  for (const [code, kind] of PAGES) {
    files.push(yamlBlock(`${code}.html`, pageHtml(code, kind)));
    files.push(yamlBlock(`${code}.json`, jsonBody(code, kind)));
  }
  return `# GENERATED by scripts/build_friendly_errors.mjs. Do not edit.
# Branded error pages for the ingress. ingress-nginx sends the original status in X-Code and the
# original Accept header in X-Format; browsers get the mascot page, API clients get JSON.
apiVersion: v1
kind: ConfigMap
metadata:
  name: friendly-errors-pages
  namespace: aoep
data:
${files.join("\n")}
---
apiVersion: v1
kind: ConfigMap
metadata:
  name: friendly-errors-nginx
  namespace: aoep
data:
  default.conf: |
    map $http_x_format $fe_ext { default json; "~*text/html" html; }
    server {
      listen 8080;
      root /pages;
      location = /healthz { access_log off; return 200 "ok"; }
      location @err { rewrite ^ /$http_x_code.$fe_ext break; add_header Cache-Control "no-store" always; }
      location / {
        if ($http_x_code = 404) { return 404; }
        if ($http_x_code = 502) { return 502; }
        if ($http_x_code = 503) { return 503; }
        if ($http_x_code = 504) { return 504; }
        return 500;
      }
      error_page 404 500 502 503 504 @err;
      types { text/html html; application/json json; }
    }
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: friendly-errors
  namespace: aoep
spec:
  replicas: 2
  selector: { matchLabels: { app: friendly-errors } }
  template:
    metadata: { labels: { app: friendly-errors } }
    spec:
      containers:
        - name: nginx
          image: nginx:1.27-alpine
          ports: [{ containerPort: 8080 }]
          resources: { requests: { cpu: 5m, memory: 12Mi }, limits: { cpu: 100m, memory: 64Mi } }
          readinessProbe: { httpGet: { path: /healthz, port: 8080 } }
          volumeMounts:
            - { name: pages, mountPath: /pages }
            - { name: conf, mountPath: /etc/nginx/conf.d/default.conf, subPath: default.conf }
      volumes:
        - { name: pages, configMap: { name: friendly-errors-pages } }
        - { name: conf, configMap: { name: friendly-errors-nginx } }
---
apiVersion: v1
kind: Service
metadata:
  name: friendly-errors
  namespace: aoep
spec:
  selector: { app: friendly-errors }
  ports: [{ port: 80, targetPort: 8080 }]
`;
}

export function buildAll() {
  const out = {};
  const js = sharedStaticJs();
  out["packages/shared/src/aoep_shared/static/friendly_error.js"] = js;
  out["subrepos/theodore_children_webcam_lab/src/theodore_children_webcam_lab/static/friendly_error.js"] = js;
  out["subrepos/theodore_course_studio/src/theodore_course_studio/voice_static/friendly_error.js"] = js;
  out["apps/web/app/lib/friendlyError.generated.ts"] = tsModule(artAnimated);
  out["apps/mobile/src/friendlyError.generated.ts"] = tsModule(artStatic);
  out["packages/shared/src/aoep_shared/static/friendly_error_copy.json"] = JSON.stringify(COPY, null, 2) + "\n";
  out["infra/k8s-vke/friendly-errors.yaml"] = k8sManifest();
  out["apps/web/public/errors/503.html"] = pageHtml(503, "network");
  return out;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes("--check");
  let stale = 0;
  for (const [rel, content] of Object.entries(buildAll())) {
    const file = join(ROOT, rel);
    if (check) {
      if (!existsSync(file) || readFileSync(file, "utf8") !== content) { console.error(`stale: ${rel}`); stale += 1; }
    } else {
      mkdirSync(dirname(file), {recursive: true});
      writeFileSync(file, content);
      console.log(`wrote ${rel}`);
    }
  }
  if (check && stale) { console.error("Run: node scripts/build_friendly_errors.mjs"); process.exit(1); }
}
void classifyStatus;
